type Listener = (payload: any) => void;

export class EventBus {
    private listeners: { [eventName: string]: Listener[] } = {};

    subscribe(eventName: string, listener: Listener) {
        if (!this.listeners[eventName]) {
            this.listeners[eventName] = [];
        }
        this.listeners[eventName].push(listener);
    }

    publish(eventName: string, payload: any) {
        if (this.listeners[eventName]) {
            this.listeners[eventName].forEach(listener => {
                try {
                    listener(payload);
                } catch (e) {
                    console.error(`Error in event listener for ${eventName}:`, e);
                }
            });
        }
    }
}

export const eventBus = new EventBus();

export interface User {
    id: string;
    name: string;
    email: string;
}

export class UserService {
    private users = new Map<string, User>();
    private nextId = 1;

    createUser(name: string, email: string): User {
        const id = `user-${this.nextId++}`;
        const user: User = { id, name, email };
        this.users.set(id, user);
        return user;
    }

    getUser(id: string): User | undefined {
        return this.users.get(id);
    }

    getAllUsers(): User[] {
        return Array.from(this.users.values());
    }

    updateUser(id: string, name: string, email: string): User | undefined {
        const user = this.users.get(id);
        if (user) {
            user.name = name;
            user.email = email;
            this.users.set(id, user);
            return user;
        }
        return undefined;
    }

    deleteUser(id: string): boolean {
        return this.users.delete(id);
    }
}

export interface Project {
    id: string;
    name: string;
    description: string;
    memberIds: string[];
}

export class ProjectService {
    private projects = new Map<string, Project>();
    private nextId = 1;

    createProject(name: string, description: string): Project {
        const id = `proj-${this.nextId++}`;
        const project: Project = { id, name, description, memberIds: [] };
        this.projects.set(id, project);
        return project;
    }

    getProject(id: string): Project | undefined {
        return this.projects.get(id);
    }

    getAllProjects(): Project[] {
        return Array.from(this.projects.values());
    }

    updateProject(id: string, name: string, description: string): Project | undefined {
        const project = this.projects.get(id);
        if (project) {
            project.name = name;
            project.description = description;
            return project;
        }
        return undefined;
    }

    deleteProject(id: string): boolean {
        return this.projects.delete(id);
    }

    addMemberToProject(id: string, memberId: string): Project | undefined {
        const project = this.projects.get(id);
        if (project && !project.memberIds.includes(memberId)) {
            project.memberIds.push(memberId);
            return project;
        }
        return undefined;
    }

    removeMemberFromProject(id: string, memberId: string): Project | undefined {
        const project = this.projects.get(id);
        if (project) {
            const index = project.memberIds.indexOf(memberId);
            if (index > -1) {
                project.memberIds.splice(index, 1);
                return project;
            }
        }
        return undefined;
    }
}

import { eventBus } from './event-bus';

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface Task {
    id: string;
    projectId: string;
    title: string;
    description: string;
    status: TaskStatus;
    assigneeId?: string;
}

export class TaskService {
    private tasks = new Map<string, Task>();
    private nextId = 1;

    createTask(projectId: string, title: string, description: string): Task {
        const id = `task-${this.nextId++}`;
        const task: Task = { id, projectId, title, description, status: 'todo' };
        this.tasks.set(id, task);
        return task;
    }

    getTask(id: string): Task | undefined {
        return this.tasks.get(id);
    }

    getTasksByProject(projectId: string): Task[] {
        return Array.from(this.tasks.values()).filter(task => task.projectId === projectId);
    }

    updateTask(id: string, title: string, description: string): Task | undefined {
        const task = this.tasks.get(id);
        if (task) {
            task.title = title;
            task.description = description;
            return task;
        }
        return undefined;
    }

    deleteTask(id: string): boolean {
        return this.tasks.delete(id);
    }

    updateTaskStatus(id: string, status: TaskStatus): Task | undefined {
        const task = this.tasks.get(id);
        if (!task) {
            return undefined;
        }

        const validTransitions: { [key in TaskStatus]?: TaskStatus[] } = {
            'todo': ['in-progress'],
            'in-progress': ['done']
        };

        if (validTransitions[task.status]?.includes(status)) {
            task.status = status;
            eventBus.publish('task.statusChanged', task);
            return task;
        }

        return undefined;
    }

    assignTask(id: string, assigneeId: string): Task | undefined {
        const task = this.tasks.get(id);
        if (task) {
            task.assigneeId = assigneeId;
            eventBus.publish('task.assigned', task);
            return task;
        }
        return undefined;
    }
}

